add_filter( 'woocommerce_product_get_upsell_ids', 'perfectpixel_default_upsells', 10, 2 );

function perfectpixel_default_upsells( $ids, $product ) {
	if ( ! empty( $ids ) || ! $product ) {
		return $ids;
	}
	return array_values( array_diff( wp_parse_id_list( '{{default_upsell_ids}}' ), array( $product->get_id() ) ) );
}
